138	let lastRequestStart = 0;
139	async function politeGate() {
140	  const now = Date.now();
141	  const at = Math.max(now, lastRequestStart + CONFIG.requestGapMs);
142	  lastRequestStart = at;
143	  if (at > now) await sleep(at - now);
144	}
