146	async function downloadChunkOnce(ctx, entry, eff, chunk, effGen) {
147	  const start = chunk * eff.chunkSize;
148	  const end =
149	    eff.expectedBytes != null ? Math.min(start + eff.chunkSize - 1, eff.expectedBytes - 1) : start + eff.chunkSize - 1;
150	  const dest = chunkPath(eff.id, chunk);
151	  const tmp = `${dest}.tmp`;
152	  await fs.mkdir(path.dirname(dest), { recursive: true });
153	  const ifRange = eff.etag || eff.lastModified || null;
154	
155	  await politeGate();
156	  let meta;
157	  try {
158	    meta = await httpGetToFile(eff.url, {
159	      destTmp: tmp,
160	      start,
161	      end,
162	      ifRange,
163	      limiter: ctx.limiter,
164	      idleTimeoutMs: CONFIG.idleTimeoutMs,
165	      attemptTimeoutMs: CONFIG.attemptTimeoutMs,
166	    });
167	  } catch (err) {
168	    // An If-Range mismatch makes the server send the full entity (200). That is
169	    // a validator change, not a plain ignored Range; reset and refetch.
170	    if (err.rangeIgnored && ifRange) {
171	      await fs.rm(tmp, { force: true });
172	      const e = new Error('validator changed (If-Range mismatch: server sent full body)');
173	      e.validatorChanged = true;
174	      throw e;
175	    }
176	    await fs.rm(tmp, { force: true });
177	    throw err;
178	  }
179	
180	  if (effGen !== undefined && eff.gen !== effGen) {
181	    await fs.rm(tmp, { force: true });
182	    const err = new Error('file reset during download');
183	    err.aborted = true;
184	    throw err;
185	  }
186	  if (eff.etag && meta.etag && meta.etag !== eff.etag) {
187	    await fs.rm(tmp, { force: true });
188	    const err = new Error('validator (ETag) changed');
189	    err.validatorChanged = true;
190	    throw err;
191	  }
192	
193	  let total = eff.expectedBytes;
194	  if (meta.contentRange && meta.contentRange.total != null) total = meta.contentRange.total;
195	  if (meta.status === 200 && meta.contentLength != null) total = meta.contentLength;
196	  if (total == null) {
197	    await fs.rm(tmp, { force: true });
198	    throw new TransientError('no total size available (server without validators)');
199	  }
200	
201	  const expectedThis = meta.status === 200 ? total : Math.min(eff.chunkSize, total - start);
202	  if (meta.bytesWritten !== expectedThis) {
203	    await fs.rm(tmp, { force: true });
204	    throw new TransientError(`short body ${meta.bytesWritten}/${expectedThis}`);
205	  }
206	  const hash = await sha256File(tmp);
207	  await fs.rename(tmp, dest);
208	  return {
209	    bytes: meta.bytesWritten,
210	    sha256: hash,
211	    total,
212	    etag: meta.etag || eff.etag,
213	    lastModified: meta.lastModified || eff.lastModified,
214	    wholeBody: meta.status === 200,
215	  };
216	}
