218	async function withRetries(ctx, eff, chunkIndex, fn) {
219	  let attempt = 0;
220	  let backoff = CONFIG.baseBackoffMs;
221	  for (;;) {
222	    attempt++;
223	    eff.attempts++;
224	    try {
225	      return await fn(attempt);
226	    } catch (err) {
227	      eff.lastError = err.message;
228	      eff.lastErrorAt = new Date().toISOString();
229	      if (err.validatorChanged || err.aborted || err.rangeIgnored || err.permanent || err.rangeNotSatisfiable) throw err;
230	      eff.retries++;
231	      if (attempt >= CONFIG.maxAttemptsPerChunk) throw err;
232	      let wait = err.retryAfterMs != null ? err.retryAfterMs : backoff;
233	      wait = Math.max(wait, CONFIG.requestGapMs);
234	      ctx.log(`retry ${eff.id} chunk ${chunkIndex} #${attempt}: ${err.message} (wait ${Math.round(wait)}ms)`);
235	      await sleep(jitter(wait));
236	      backoff = Math.min(CONFIG.maxBackoffMs, backoff * 2);
237	    }
238	  }
239	}
