241	function applyChunkResult(eff, i, info, effGen) {
242	  if (effGen !== undefined && eff.gen !== effGen) return false;
243	  eff.chunks[i] = { bytes: info.bytes, sha256: info.sha256 };
244	  eff.expectedBytes = info.total ?? eff.expectedBytes;
245	  eff.etag = info.etag || eff.etag;
246	  eff.lastModified = info.lastModified || eff.lastModified;
247	  eff.receivedBytes = Object.values(eff.chunks).reduce((a, c) => a + c.bytes, 0);
248	  eff.cleanupPasses = 0;
249	  return true;
250	}
