252	function resetForRetry(eff, reason) {
253	  eff.chunks = {};
254	  eff.receivedBytes = 0;
255	  eff.gen = (eff.gen || 0) + 1;
256	  if (reason === 'validatorChanged' || reason === 'rangeIgnored') {
257	    eff.etag = null;
258	    eff.lastModified = null;
259	  }
260	  eff.status = 'pending';
261	  eff.lastError = reason;
262	}
