264	export async function downloadFile(ctx, entry) {
265	  const { state, pool } = ctx;
266	  const eff = ensureFileEntry(state, entry);
267	  if (eff.status === 'published') return { done: true };
268	  eff.status = 'in_progress';
269	  const gen = eff.gen;
270	
271	  // Chunk 0 establishes size (or the whole body when the range is ignored).
272	  if (eff.expectedBytes == null || !eff.chunks[0]) {
273	    try {
274	      const info = await withRetries(ctx, eff, 0, () => downloadChunkOnce(ctx, entry, eff, 0, gen));
275	      applyChunkResult(eff, 0, info, gen);
276	      await saveState(state);
277	    } catch (err) {
278	      if (err.validatorChanged || err.aborted || err.rangeIgnored) {
279	        resetForRetry(eff, err.validatorChanged ? 'validatorChanged' : err.rangeIgnored ? 'rangeIgnored' : 'aborted');
280	      } else if (err.permanent) {
281	        eff.status = 'unavailable';
282	      }
283	      await saveState(state);
284	      throw err;
285	    }
286	  }
287	
288	  const n = chunkCount(eff);
289	  const missing = [];
290	  for (let i = 0; i < n; i++) {
291	    if (eff.chunks[i] && (await fileValid(eff.id, i, eff.chunks[i]))) continue;
292	    missing.push(i);
293	  }
294	
295	  const failures = [];
296	  await Promise.all(
297	    missing.map((i) =>
298	      pool.run(async () => {
299	        const myGen = eff.gen;
300	        try {
301	          const info = await withRetries(ctx, eff, i, () => downloadChunkOnce(ctx, entry, eff, i, myGen));
302	          if (applyChunkResult(eff, i, info, myGen)) await saveState(state);
303	        } catch (err) {
304	          failures.push({ i, err });
305	        }
306	      }),
307	    ),
308	  );
309	
310	  if (failures.length > 0) {
311	    const hard = failures.find((f) => f.err.validatorChanged || f.err.aborted || f.err.rangeIgnored);
312	    if (hard) {
313	      resetForRetry(eff, hard.err.validatorChanged ? 'validatorChanged' : hard.err.rangeIgnored ? 'rangeIgnored' : 'aborted');
314	    } else if (failures.every((f) => f.err.permanent)) {
315	      eff.status = 'unavailable';
316	    }
317	    await saveState(state);
318	    return { done: false, failures: failures.map((f) => f.err.message) };
319	  }
320	
321	  const haveAll = chunkCount(eff) > 0 && (await allChunksValid(eff));
322	  if (haveAll) {
323	    eff.receivedBytes = Object.values(eff.chunks).reduce((a, c) => a + c.bytes, 0);
324	    return { done: true };
325	  }
326	  return { done: false };
327	}
