384	export async function publishFile(ctx, entry) {
385	  const { state, ghcr, log } = ctx;
386	  const eff = ensureFileEntry(state, entry);
387	  const tag = entryTag(entry);
388	  const work = path.join(workspaceDir(eff.id), 'out', `${eff.id}.bin`);
389	
390	  const { sha256, bytes } = await assembleHex(eff);
391	  await assembleToFile(eff, work);
392	
393	  log(`publishing ${eff.id} (${bytes} bytes) as ${tag}`);
394	  const push = await ghcr.pushFile(tag, work, {
395	    title: eff.filename,
396	    annotations: {
397	      'org.opencontainers.image.title': eff.filename,
398	      'shurik.nauka.year': String(eff.year),
399	      'shurik.nauka.issue': eff.issue,
400	      'shurik.nauka.format': eff.format,
401	      'shurik.nauka.sha256': sha256,
402	      'shurik.nauka.source-url': eff.url,
403	      'shurik.nauka.index-url': ctx.manifest.indexUrl,
404	    },
405	  });
406	
407	  eff.sha256 = sha256;
408	  eff.expectedBytes = bytes;
409	  eff.ghcr = { tag, digest: push.digest, title: eff.filename, pushedAt: new Date().toISOString() };
410	  await saveState(state);
411	
412	  // Round-trip verification: pull the tag back and compare bytes.
413	  const verifyDir = path.join(PATHS.stagingDir, 'verify', eff.id);
414	  await fs.rm(verifyDir, { recursive: true, force: true });
415	  await ghcr.pull(tag, verifyDir);
416	  const pulled = path.join(verifyDir, path.basename(work));
417	  const pulledHash = await sha256File(pulled);
418	  const ok = pulledHash === sha256;
419	  eff.verified = { at: new Date().toISOString(), pulledSha256: pulledHash, ok, digest: push.digest };
420	  await fs.rm(verifyDir, { recursive: true, force: true });
421	  if (!ok) {
422	    eff.status = 'in_progress';
423	    eff.lastError = 'round-trip verification mismatch';
424	    eff.lastErrorAt = new Date().toISOString();
425	    await saveState(state);
426	    throw new Error(`round-trip verification failed for ${eff.id}`);
427	  }
428	  eff.status = 'published';
429	  eff.publishedAt = new Date().toISOString();
430	  eff.lastError = null;
431	  await saveState(state);
432	
433	  await fs.rm(workspaceDir(eff.id), { recursive: true, force: true });
434	  await clearGitPartial(eff.id);
435	  await saveState(state);
436	  log(`verified ${eff.id}: ${sha256}`);
437	  return { sha256, bytes, digest: push.digest, tag };
438	}
