448	export async function checkpointPartials(ctx) {
449	  const { state, ghcr, log } = ctx;
450	  const inProgress = Object.values(state.files).filter(
451	    (e) => e.status === 'in_progress' && Object.keys(e.chunks).length > 0,
452	  );
453	
454	  // Selected small prefixes on the control branch.
455	  await fs.mkdir(PATHS.partialDir, { recursive: true });
456	  const partialIndex = { version: 1, updatedAt: new Date().toISOString(), partials: {} };
457	  let budget = CONFIG.gitPartialMaxTotalBytes;
458	  for (const eff of inProgress) {
459	    if (budget <= 0) break;
460	    const prefix = await buildContiguousPrefix(eff.id, eff.chunks, eff.chunkSize);
461	    if (!prefix || prefix.bytes === 0) continue;
462	    const cap = Math.min(prefix.bytes, CONFIG.gitPartialMaxBytesPerFile, budget);
463	    const buf = prefix.buffer.subarray(0, cap);
464	    await atomicWriteFile(path.join(PATHS.partialDir, `${eff.id}.prefix`), buf);
465	    partialIndex.partials[eff.id] = {
466	      bytes: buf.length,
467	      sha256: sha256Buf(buf),
468	      chunkSize: eff.chunkSize,
469	      at: new Date().toISOString(),
470	    };
471	    budget -= buf.length;
472	  }
473	  await atomicWriteJson(PARTIAL_INDEX, partialIndex);
474	
475	  // Full chunk workspaces to GHCR checkpoint artifacts.
476	  for (const eff of inProgress) {
477	    const dir = chunksDir(eff.id);
478	    let names = [];
479	    try {
480	      names = (await fs.readdir(dir)).filter((f) => f.startsWith('chunk-'));
481	    } catch {
482	      continue;
483	    }
484	    if (names.length === 0) continue;
485	    for (const f of await fs.readdir(dir)) {
486	      if (f.endsWith('.tmp')) await fs.rm(path.join(dir, f), { force: true });
487	    }
488	    const bytes = (
489	      await Promise.all(names.map(async (f) => (await fs.stat(path.join(dir, f))).size))
490	    ).reduce((a, b) => a + b, 0);
491	    if (eff.checkpoint && eff.checkpoint.bytes === bytes) continue;
492	    try {
493	      const res = await ghcr.pushDir(checkpointTag(eff.id), dir);
494	      eff.checkpoint = { digest: res.digest, bytes, chunks: names.length, at: new Date().toISOString() };
495	      log(`checkpointed ${eff.id} (${bytes} bytes, ${names.length} chunks) -> ${res.digest}`);
496	    } catch (err) {
497	      log(`checkpoint push failed for ${eff.id}: ${err.message}`);
498	    }
499	    await saveState(state);
500	  }
501	  return partialIndex;
502	}
