520	export async function restoreFromGitPartials(state, log = () => {}) {
521	  const idx = await loadJson(PARTIAL_INDEX, null);
522	  if (!idx) return 0;
523	  let restored = 0;
524	  for (const [id, info] of Object.entries(idx.partials || {})) {
525	    const eff = state.files[id];
526	    if (!eff || eff.status === 'published') continue;
527	    let buf;
528	    try {
529	      buf = await fs.readFile(path.join(PATHS.partialDir, `${id}.prefix`));
530	    } catch {
531	      continue;
532	    }
533	    if (buf.length !== info.bytes || sha256Buf(buf) !== info.sha256) {
534	      log(`ignoring torn git partial for ${id}`);
535	      continue;
536	    }
537	    const nChunks = Math.ceil(buf.length / info.chunkSize);
538	    for (let i = 0; i < nChunks; i++) {
539	      const start = i * info.chunkSize;
540	      const chunkBuf = buf.subarray(start, Math.min(start + info.chunkSize, buf.length));
541	      const ci = eff.chunks[i];
