597	
598	export function createPool(size) {
599	  let active = 0;
600	  const queue = [];
601	  const next = () => {
602	    if (active >= size || queue.length === 0) return;
603	    active++;
604	    const { fn, resolve, reject } = queue.shift();
605	    Promise.resolve()
606	      .then(fn)
607	      .then(resolve, reject)
608	      .finally(() => {
609	        active--;
610	        next();
611	      });
612	  };
613	  return {
614	    run(fn) {
615	      return new Promise((resolve, reject) => {
616	        queue.push({ fn, resolve, reject });
617	        next();
618	      });
619	    },
620	    get active() {
621	      return active;
622	    },
623	  };
624	}
