626	export function estimateBytes(labelSize) {
627	  const m = /(\d+(?:\.\d+)?)\s*M/i.exec(labelSize || '');
628	  return m ? Math.round(Number(m[1]) * 1024 * 1024) : null;
629	}
630	
631	export function orderEntries(entries, state) {
632	  return [...entries].sort((a, b) => {
633	    const ea = state.files[a.id];
634	    const eb = state.files[b.id];
635	    const pa = ea && ea.status === 'published';
636	    const pb = eb && eb.status === 'published';
637	    if (pa !== pb) return pa ? 1 : -1;
638	    const sa = (ea && ea.expectedBytes) || estimateBytes(a.labelSize) || 1e12;
639	    const sb = (eb && eb.expectedBytes) || estimateBytes(b.labelSize) || 1e12;
640	    return sa - sb;
641	  });
642	}
