644	export function createContext({ state, manifest, ghcr, log = console.log }) {
645	  return {
646	    state,
647	    manifest,
648	    ghcr,
649	    log,
650	    limiter: createRateLimiter(CONFIG.bandwidthLimitBps),
651	    pool: createPool(CONFIG.maxConcurrency),
652	  };
653	}
