655	export async function runPass(ctx) {
656	  const { state, manifest, log } = ctx;
657	  const deadline = Date.now() + CONFIG.passBudgetMs;
658	  const ordered = orderEntries(manifest.entries, state);
659	  const results = [];
660	  for (const entry of ordered) {
661	    if (Date.now() >= deadline) break;
662	    const eff = ensureFileEntry(state, entry);
663	    if (eff.status === 'published' || eff.status === 'unavailable') continue;
