import { promises as fs } from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { CONFIG, PATHS, REGISTRY, entryTag, checkpointTag, ARTIFACT_TYPE } from './config.mjs';
import {
